// src/sessionStore.mjs
import { LRU } from './lru.mjs';
import { BackingStore } from './backingStore.mjs';

// Sessions live in an in-memory LRU; the backing store is the overflow.
export class SessionStore {
  constructor({ maxInMemory = 1000, backing = new BackingStore() } = {}) {
    this.backing = backing;
    this.lru = new LRU({
      max: maxInMemory,
      onEvict: (key, value, reason) => {
        if (reason === 'capacity') {
          this.backing.save(key, value);
        }
      },
    });
  }

  create(id, data = {}) {
    const session = { id, data };
    this.lru.set(id, session);
    // If there was a stale copy in backing (e.g., re-create same id), remove it
    // because the live version is now in memory.
    if (this.backing.has(id)) {
      // Only remove if the in-memory version is the newly created one;
      // but for create we always want backing to not hold duplicate.
      // However if the id was just evicted and we are recreating, we should drop old.
      // The simplest: if we just set in LRU, ensure backing doesn't also hold it
      // unless it was just saved via capacity eviction of another key.
      // So check if the key we just set is still in LRU (it is) -> remove backing copy of same id.
      // This avoids stale data when create overwrites an evicted session.
      this.backing.remove(id);
    }
    return session;
  }

  get(id) {
    const fromLru = this.lru.get(id);
    if (fromLru !== undefined) {
      return fromLru;
    }
    const fromBacking = this.backing.load(id);
    if (fromBacking !== undefined) {
      this.backing.remove(id);
      this.lru.set(id, fromBacking);
      return fromBacking;
    }
    return undefined;
  }

  update(id, patch) {
    const s = this.get(id);
    if (!s) throw new Error(`no session ${id}`);
    const next = { ...s, data: { ...s.data, ...patch } };
    this.lru.set(id, next);
    return next;
  }

  /** Logout. */
  destroy(id) {
    this.lru.delete(id);
    this.backing.remove(id);
  }
}
```

