```mjs
// Small TTL + size-bounded cache used by service layers.
// Values are stored with an expiry timestamp computed from the injected clock.
// When maxSize is exceeded the oldest inserted entry is evicted.

export class TtlCache {
  /**
   * @param {{ ttlMs?: number, maxSize?: number, now?: () => number }} [opts]
   */
  constructor({ ttlMs = 60_000, maxSize = 1000, now = () => Date.now() } = {}) {
    this.ttlMs = ttlMs;
    this.maxSize = maxSize;
    this.now = now;
    /** @type {Map<string, { value: unknown, expiresAt: number }>} */
    this.entries = new Map();
    /** @type {Map<string, Promise<unknown>>} */
    this.inFlight = new Map();
  }

  get size() {
    return this.entries.size;
  }

  has(key) {
    return this.get(key) !== undefined;
  }

  /** Synchronous lookup. Returns the stored value or undefined. */
  get(key) {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    if (this.now() >= entry.expiresAt) {
      this.entries.delete(key);
      return undefined;
    }
    return entry.value;
  }

  set(key, value) {
    this.entries.delete(key);
    this.entries.set(key, { value, expiresAt: this.now() + this.ttlMs });
    while (this.entries.size > this.maxSize) {
      const oldest = this.entries.keys().next().value;
      this.entries.delete(oldest);
    }
  }

  delete(key) {
    return this.entries.delete(key);
  }

  /**
   * Return the cached value for key, or call loader(key), store and return its result.
   * Concurrent callers for the same key share a single in-flight load.
   */
  async getOrLoad(key, loader) {
    const hit = this.get(key);
    if (hit !== undefined) return hit;

    const existing = this.inFlight.get(key);
    if (existing) {
      return existing;
    }

    const loadPromise = Promise.resolve()
      .then(() => loader(key))
      .then((value) => {
        this.set(key, value);
        return value;
      });

    // Ensure in-flight entry is cleared after settlement, for both success and failure.
    // Attach cleanup without creating a new promise that callers would miss.
    const withCleanup = loadPromise.then(
      (v) => {
        this.inFlight.delete(key);
        return v;
      },
      (err) => {
        this.inFlight.delete(key);
        throw err;
      }
    );

    // Store the promise that callers will share (the one that resolves to the value,
    // but we keep cleanup attached via withCleanup to avoid race where delete happens
    // before settlement and a new load starts).
    // To avoid the race, keep original promise in map and delete in both handlers,
    // but return a promise that includes cleanup. Simplest: store withCleanup and return it.
    // Actually we need deletion after settlement, so storing withCleanup is fine because
    // all callers get the same promise reference.
    this.inFlight.set(key, withCleanup);

    return withCleanup;
  }
}
```

