import { LRU } from './lru.mjs';
import { BackingStore } from './backingStore.mjs';

// Sessions live in an in-memory LRU; the backing store is the overflow.
export class SessionStore {
  constructor({ maxInMemory = 1000, backing = new BackingStore() } = {}) {
    this.backing = backing;
    this.lru = new LRU({
      max: maxInMemory,
      onEvict: (key, value, reason) => {
        if (reason === 'capacity') {
          this.backing.save(key, value);
        }
      },
    });
  }

  create(id, data = {}) {
    const session = { id, data };
    this.lru.set(id, session);
    this.backing.remove(id);
    return session;
  }

  get(id) {
    const fromLru = this.lru.get(id);
    if (fromLru !== undefined) return fromLru;
    const fromBacking = this.backing.load(id);
    if (fromBacking !== undefined) {
      this.lru.set(id, fromBacking);
      this.backing.remove(id);
      return fromBacking;
    }
    return undefined;
  }

  update(id, patch) {
    const s = this.get(id);
    if (!s) throw new Error(`no session ${id}`);
    const next = { ...s, data: { ...s.data, ...patch } };
    this.lru.set(id, next);
    return next;
  }

  /** Logout. */
  destroy(id) {
    this.lru.delete(id);
    this.backing.remove(id);
