 // Rounding helpers for integer-cent money math.

/**
 * Round a cent amount half-up (2.5 -> 3, -2.5 -> -2), i.e. Math.round semantics.
 * Used by: invoice.mjs (line tax), statement.mjs (late fees - half-up is
 * written into the customer agreement, do not change for statements).
 */
export function roundCents(x) {
  return Math.round(x);
}

/**
 * Banker's rounding (round half to even) for a floating value.
 * Symmetric for negatives: -2.5 -> -2, -3.5 -> -4.
 */
export function roundHalfEven(x) {
  if (!Number.isFinite(x)) return Math.round(x);
  if (x === 0) return 0;
  const sign = x < 0 ? -1 : 1;
  const abs = Math.abs(x);
  const floor = Math.floor(abs);
  const frac = abs - floor;
  const eps = 1e-12;
  let roundedAbs;
  if (Math.abs(frac - 0.5) < eps) {
    roundedAbs = floor % 2 === 0 ? floor : floor + 1;
  } else {
    roundedAbs = Math.round(abs);
  }
  const res = sign * roundedAbs;
  return res === 0 ? 0 : res;
}

/**
 * Banker's rounding of numerator/denominator.
 * Uses integer remainder comparison (r*2 vs den) when possible to avoid
 * floating errors. Symmetric for negatives.
 */
export function roundDivHalfEven(numerator, denominator) {
  if (denominator === 0) throw new RangeError('denominator must not be 0');
  if (numerator === 0) return 0;
  const sign = Math.sign(numerator) * Math.sign(denominator);
  const absNum = Math.abs(numerator);
  const absDen = Math.abs(denominator);

  // If both are integers, use exact integer arithmetic
  if (Number.isInteger(absNum) && Number.isInteger(absDen)) {
    const q = Math.trunc(absNum / absDen);
    const r = absNum % absDen;
    const twiceR = r * 2;
    let roundedAbs;
    if (twiceR < absDen) {
      roundedAbs = q;
    } else if (twiceR > absDen) {
      roundedAbs = q + 1;
    } else {
      // exactly half
      roundedAbs = q % 2 === 0 ? q : q + 1;
    }
    const res = sign * roundedAbs;
    return res === 0 ? 0 : res;
  }

  // Fallback for non-integers
  return roundHalfEven(numerator / denominator);
}
